    internal sealed class StrategyAnalysisRecord
    {
        public string Id { get; set; }
        public string ModelId { get; set; }
        public string CreatedUtc { get; set; }
        public string ModelFingerprint { get; set; }
        public string AnalysisFingerprint { get; set; }
        public string CertificateHash { get; set; }
        public int CaseCount { get; set; }
        public string RecommendedPolicyId { get; set; }
        public string RecommendationRule { get; set; }
        public List<StrategyPolicyEvaluation> Policies { get; set; }
        public List<StrategyInformationValue> InformationValues { get; set; }
        public StrategyAnalysisRecord() { Policies = new List<StrategyPolicyEvaluation>(); InformationValues = new List<StrategyInformationValue>(); }
        public override string ToString() { return (CreatedUtc ?? "") + "   ·   " + CaseCount.ToString(CultureInfo.InvariantCulture) + " cases   ·   recommendation " + (RecommendedPolicyId ?? "∅") + "   ·   cert " + ShortHash(CertificateHash); }
        private static string ShortHash(string value) { return String.IsNullOrWhiteSpace(value) ? "∅" : value.Substring(0, Math.Min(16, value.Length)); }
    }

