        public static void OpenFromWorldNode(Window owner, DeepSystemsContext ctx, WorldIndex index, string nodeId)
        {
            if (ctx == null || index == null || String.IsNullOrWhiteSpace(nodeId)) return; Load(ctx); WorldNode node; if (!index.Nodes.TryGetValue(nodeId, out node)) { Open(owner, ctx); return; } string fingerprint = HashText((node.Id ?? "") + "|" + (node.Kind ?? "") + "|" + (node.Label ?? "") + "|" + (node.Fingerprint ?? "")); StrategyModel existing = LatestProjection("WORLD", node.Id); if (existing != null && String.Equals(existing.SourceFingerprint, fingerprint, StringComparison.OrdinalIgnoreCase)) { OpenModel(owner, ctx, index, existing); return; }
            Window w = W(owner, "YOMI · STRATEGY INGRESS · " + (node.Label ?? node.Kind), 1040, 720); DockPanel root = Shell("WORLD PASSPORT → COUNTERFACTUAL STRATEGY", (node.Kind ?? "OBJECT") + " · " + (node.Label ?? node.Id) + "\r\nSource identity remains evidence, never a causal coefficient by itself."); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 8, 0, 10) }; tools.Children.Add(Btn(existing == null ? "FOUND STRATEGY MODEL" : "CREATE CURRENT PROJECTION", delegate { StrategyModel model = ProjectWorldNode(ctx, node, fingerprint); OpenModel(w, ctx, index, model); })); if (existing != null) tools.Children.Add(Btn("OPEN HISTORICAL PROJECTION", delegate { OpenModel(w, ctx, index, existing); })); tools.Children.Add(Btn("OPEN WORLD PASSPORT", delegate { WorldKernel.ExternalOpenDossier(w, ctx, index, node.Id); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); root.Children.Add(ReadOnly(DescribeNode(node))); w.Content = root; w.Show();
        }

        public static void OpenFromCivilResolution(Window owner, DeepSystemsContext ctx, WorldIndex index, CivilResolution resolution)
        {
            if (ctx == null || resolution == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); string fingerprint = HashText((resolution.Id ?? "") + "|" + (resolution.Title ?? "") + "|" + (resolution.Proposition ?? "") + "|" + (resolution.EpistemicClass ?? "") + "|" + (resolution.Status ?? "") + "|" + String.Join("|", (resolution.EvidenceNodeIds ?? new List<string>()).OrderBy(x => x).ToArray())); StrategyModel existing = LatestProjection("CIVILIZATION", resolution.Id); if (existing != null && String.Equals(existing.SourceFingerprint, fingerprint, StringComparison.OrdinalIgnoreCase)) { OpenModel(owner, ctx, target, existing); return; } if (existing != null) { string action = Choose(owner, "RESOLUTION STRATEGY DRIFT", "The resolution changed after its earlier causal projection. Preserve the historical strategy boundary or build a new projection?", new[] { "OPEN HISTORICAL MODEL", "CREATE CURRENT PROJECTION" }, "OPEN HISTORICAL MODEL"); if (action == "OPEN HISTORICAL MODEL") { OpenModel(owner, ctx, target, existing); return; } if (action != "CREATE CURRENT PROJECTION") return; } OpenModel(owner, ctx, target, ProjectResolution(ctx, resolution, fingerprint));
        }

        public static void OpenFromLogicTheory(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicTheory theory)
        {
            if (ctx == null || theory == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); Dictionary<string, string> truth = EpistemicLogicFoundry.ExternalTheoryTruth(ctx, theory); string fingerprint = HashText((theory.Id ?? "") + "|" + (theory.Name ?? "") + "|" + (theory.Status ?? "") + "|" + String.Join("|", truth.OrderBy(x => x.Key).Select(x => x.Key + "=" + x.Value).ToArray())); StrategyModel existing = LatestProjection("LOGIC", theory.Id); if (existing != null && String.Equals(existing.SourceFingerprint, fingerprint, StringComparison.OrdinalIgnoreCase)) { OpenModel(owner, ctx, target, existing); return; } if (existing != null) { string action = Choose(owner, "THEORY STRATEGY DRIFT", "The frozen theory truth spectrum changed. Preserve its historical causal abstraction or build a current one?", new[] { "OPEN HISTORICAL MODEL", "CREATE CURRENT PROJECTION" }, "OPEN HISTORICAL MODEL"); if (action == "OPEN HISTORICAL MODEL") { OpenModel(owner, ctx, target, existing); return; } if (action != "CREATE CURRENT PROJECTION") return; } OpenModel(owner, ctx, target, ProjectTheory(ctx, theory, truth, fingerprint));
        }

