        private static string CensusLine() { return Store.Models.Count(x => Active(x.Status)).ToString(CultureInfo.InvariantCulture) + " active causal models · " + Store.Models.Sum(x => x.Variables.Count).ToString(CultureInfo.InvariantCulture) + " variables · " + Store.Models.Sum(x => x.Edges.Count).ToString(CultureInfo.InvariantCulture) + " mechanisms · " + Store.Models.Sum(x => x.Policies.Count).ToString(CultureInfo.InvariantCulture) + " policies · " + Store.Analyses.Count.ToString(CultureInfo.InvariantCulture) + " analyses · " + Store.Dossiers.Count.ToString(CultureInfo.InvariantCulture) + " dossiers"; }

        private static void OpenModels(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            Window w = W(owner, "YOMI · CAUSAL MODEL REGISTRY", 1200, 800); DockPanel root = Shell("STRUCTURAL CAUSAL MODEL REGISTRY", "Models are explicit bounded hypotheses about mechanisms. A coefficient is never inferred merely from a World relationship, logical proof, civil resolution or verification certificate."); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("FORGE MODEL", delegate { CreateModelPrompt(w, ctx, index); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = Store.Models.OrderBy(x => Active(x.Status) ? 0 : 1).ThenByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); list.MouseDoubleClick += delegate { StrategyModel model = list.SelectedItem as StrategyModel; if (model != null) OpenModel(w, ctx, index, model); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void CreateModelPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            string name = Prompt(owner, "FORGE CAUSAL MODEL", "Model name", "Strategic system " + DateTime.Now.ToString("yyyy-MM-dd HHmm", CultureInfo.InvariantCulture)); if (String.IsNullOrWhiteSpace(name)) return; string charter = PromptLarge(owner, "MODEL CHARTER", "Define the causal boundary, decision question and known exclusions", "A bounded structural hypothesis for comparing explicit policies. Ranges encode scenarios, not calibrated probabilities."); if (charter == null) return; StrategyModel model = StarterModel(name, charter); Store.Models.Insert(0, model); TrimStore(); Save(ctx); AppendLedger(ctx, "MODEL_FORGED", model.Id, model.Name, CounterfactualStrategyKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

        private static StrategyModel StarterModel(string name, string charter)
        {
            StrategyModel m = NewModel(name, charter, "OPERATOR", "", ""); StrategyVariable context = V("context_quality", "Context quality", "EXOGENOUS", 0.5, 0, 1, 0, true, "index"); StrategyVariable decision = V("decision_intensity", "Decision intensity", "DECISION", 0, 0, 1, 0, false, "index"); StrategyVariable value = V("strategic_value", "Strategic value", "OUTCOME", 0, 0, 1, 0.05, false, "index"); StrategyVariable risk = V("execution_risk", "Execution risk", "OUTCOME", 0, 0, 1, 0.15, false, "index"); m.Variables.AddRange(new[] { context, decision, value, risk }); m.Edges.Add(E("context_to_value", context, value, 0.40)); m.Edges.Add(E("decision_to_value", decision, value, 0.55)); m.Edges.Add(E("context_to_risk", context, risk, -0.25)); m.Edges.Add(E("decision_to_risk", decision, risk, 0.45)); m.Policies.Add(P("baseline", "Baseline / observe", decision.Id, 0)); m.Policies.Add(P("bounded", "Bounded intervention", decision.Id, 0.5)); m.Policies.Add(P("maximal", "Maximal intervention", decision.Id, 1)); m.Objectives.Add(new StrategyObjective { Id = Id("objective"), VariableId = value.Id, Name = "Strategic value", Direction = "MAXIMIZE", Weight = 0.65, Aspiration = 0.75, Status = "ACTIVE" }); m.Objectives.Add(new StrategyObjective { Id = Id("objective"), VariableId = risk.Id, Name = "Execution risk", Direction = "MINIMIZE", Weight = 0.35, Aspiration = 0.25, Status = "ACTIVE" }); m.Constraints.Add(new StrategyConstraint { Id = Id("constraint"), VariableId = risk.Id, Name = "Risk ceiling", Operator = "<=", Severity = "HARD", Threshold = 0.85, Penalty = 1, Status = "ACTIVE" }); m.Assumptions.Add("Starter coefficients are operator-editable placeholders, not empirical estimates."); m.Assumptions.Add("Uncertainty ranges are possibility coordinates and do not imply a probability distribution."); return m;
        }

