ch(model); Save(ctx); AppendLedger(ctx, "MODEL_" + model.Status, model.Id, model.Name, CounterfactualStrategyKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, model.Name, model, StorePath(ctx), "$models:" + model.Id, "STRATEGY › MODEL"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools);
