        private static void AddVariablePrompt(Window owner, DeepSystemsContext ctx, StrategyModel model)
        {
            if (model.Variables.Count >= MaxVariables) { MessageBox.Show(owner, "Variable capacity reached.", "YOMI · Structural Forge"); return; } string name = Prompt(owner, "ADD VARIABLE", "Variable name", "New variable"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "VARIABLE KIND", "Structural role", new[] { "EXOGENOUS", "ENDOGENOUS", "DECISION", "OUTCOME" }, "ENDOGENOUS"); if (kind == null) return; double baseline = Number(Prompt(owner, "BASELINE", "Baseline value", "0"), 0), minimum = Number(Prompt(owner, "DOMAIN", "Minimum value", "0"), 0), maximum = Number(Prompt(owner, "DOMAIN", "Maximum value", "1"), 1); if (maximum < minimum) { double t = minimum; minimum = maximum; maximum = t; } double intercept = Number(Prompt(owner, "STRUCTURAL INTERCEPT", "Equation intercept", kind == "ENDOGENOUS" || kind == "OUTCOME" ? "0" : baseline.ToString("R", CultureInfo.InvariantCulture)), 0); string unit = Prompt(owner, "UNIT", "Unit / scale label", "index"); string uncertain = Choose(owner, "UNCERTAINTY", "Vary across the low-discrepancy possibility manifold?", new[] { "NO", "YES" }, kind == "EXOGENOUS" ? "YES" : "NO"); StrategyVariable variable = new StrategyVariable { Id = Id("variable"), Name = Short(name, 240), Kind = kind, Status = "ACTIVE", Unit = Short(unit, 80), Baseline = baseline, Minimum = minimum, Maximum = maximum, Intercept = intercept, Uncertain = uncertain == "YES" }; model.Variables.Add(variable); Touch(model); Save(ctx); AppendLedger(ctx, "VARIABLE_ADDED", variable.Id, model.Id + " · " + variable.Name, CounterfactualStrategyKernel.Fingerprint(model), "");
        }

        private static void AddEdgePrompt(Window owner, DeepSystemsContext ctx, StrategyModel model)
        {
            if (model.Edges.Count >= MaxEdges || model.Variables.Count < 2) return; StrategyVariable from = ChooseObject(owner, "MECHANISM ORIGIN", "Select parent / cause variable", model.Variables.Cast<object>().ToList()) as StrategyVariable; if (from == null) return; StrategyVariable to = ChooseObject(owner, "MECHANISM DESTINATION", "Select child / effect variable", model.Variables.Cast<object>().ToList()) as StrategyVariable; if (to == null) return; string name = Prompt(owner, "MECHANISM", "Mechanism name", from.Name + " → " + to.Name); if (String.IsNullOrWhiteSpace(name)) return; double coefficient = Number(Prompt(owner, "COEFFICIENT", "Structural coefficient β", "1"), 1); string transform = Choose(owner, "TRANSFORM", "Parent signal transformation", new[] { "LINEAR", "LOGISTIC", "SATURATING", "HINGE", "THRESHOLD", "INVERSE" }, "LINEAR"); if (transform == null) return; double threshold = Number(Prompt(owner, "THRESHOLD", "Transform threshold / center", "0"), 0); int lag = (int)Math.Max(0, Number(Prompt(owner, "LAG", "Whole periods of causal delay", "0"), 0)); StrategyEdge edge = new StrategyEdge { Id = Id("edge"), FromVariableId = from.Id, ToVariableId = to.Id, Name = Short(name, 240), Kind = "CAUSAL", Status = "ACTIVE", Transform = transform, Coefficient = coefficient, Threshold = threshold, Lag = lag }; model.Edges.Add(edge); Touch(model); Save(ctx); AppendLedger(ctx, "MECHANISM_ADDED", edge.Id, model.Id + " · " + edge.Name, CounterfactualStrategyKernel.Fingerprint(model), "");
        }

        private static void AddObjectivePrompt(Window owner, DeepSystemsContext ctx, StrategyModel model)
