        }

        private static void AddConstraintPrompt(Window owner, DeepSystemsContext ctx, StrategyModel model)
        {
            if (model.Constraints.Count >= MaxConstraints) return; StrategyVariable variable = ChooseObject(owner, "CONSTRAINT VARIABLE", "Choose constrained variable", model.Variables.Cast<object>().ToList()) as StrategyVariable; if (variable == null) return; string name = Prompt(owner, "CONSTRAINT", "Constraint name", variable.Name + " boundary"); if (String.IsNullOrWhiteSpace(name)) return; string op = Choose(owner, "OPERATOR", "Comparison", new[] { ">=", ">", "<=", "<", "==", "!=" }, ">="); if (op == null) return; double threshold = Number(Prompt(owner, "THRESHOLD", "Constraint value", variable.Baseline.ToString("R", CultureInfo.InvariantCulture)), variable.Baseline); string severity = Choose(owner, "SEVERITY", "Hard infeasibility or soft penalty?", new[] { "HARD", "SOFT" }, "HARD"); if (severity == null) return; double penalty = severity == "SOFT" ? Math.Max(0, Number(Prompt(owner, "PENALTY", "Utility penalty when violated", "0.1"), 0.1)) : 1; model.Constraints.Add(new StrategyConstraint { Id = Id("constraint"), VariableId = variable.Id, Name = Short(name, 240), Operator = op, Threshold = threshold, Severity = severity, Penalty = penalty, Status = "ACTIVE" }); Touch(model); Save(ctx); AppendLedger(ctx, "CONSTRAINT_ADDED", model.Id, name, CounterfactualStrategyKernel.Fingerprint(model), "");
        }

        private static void EditAssumptions(Window owner, DeepSystemsContext ctx, StrategyModel model)
