        private static void AddInterventionPrompt(Window owner, DeepSystemsContext ctx, StrategyModel model, StrategyPolicy policy)
        {
            if (policy.Interventions.Count >= MaxInterventions) return; StrategyVariable variable = ChooseObject(owner, "INTERVENTION TARGET", "Select variable whose structural equation is replaced", model.Variables.Cast<object>().ToList()) as StrategyVariable; if (variable == null) return; double value = Number(Prompt(owner, "do(" + variable.Name + ")", "Intervention value within [" + variable.Minimum + ", " + variable.Maximum + "]", variable.Baseline.ToString("R", CultureInfo.InvariantCulture)), variable.Baseline); int start = (int)Math.Max(0, Number(Prompt(owner, "START PERIOD", "First active period", "0"), 0)); int end = (int)Math.Max(start, Number(Prompt(owner, "END PERIOD", "Last active period", model.Horizon.ToString(CultureInfo.InvariantCulture)), model.Horizon)); string rationale = PromptLarge(owner, "INTERVENTION RATIONALE", "Why should this hypothetical operation exist in the portfolio?", "Modeling-only intervention; implementation authority is outside this system."); if (rationale == null) return; policy.Interventions.Add(new StrategyIntervention { Id = Id("intervention"), VariableId = variable.Id, Name = "do(" + variable.Name + ")", Kind = "DO", Value = Math.Max(variable.Minimum, Math.Min(variable.Maximum, value)), StartPeriod = start, EndPeriod = end, Rationale = Short(rationale, MaxLongText) }); policy.UpdatedUtc = Now(); Touch(model); Save(ctx); AppendLedger(ctx, "INTERVENTION_ADDED", policy.Id, variable.Id + "=" + value.ToString("R", CultureInfo.InvariantCulture), CounterfactualStrategyKernel.Fingerprint(model), "");
