        private static void OpenSimulation(Window owner, DeepSystemsContext ctx, WorldIndex index, StrategyModel model, StrategyPolicy policy)
        {
            StrategySimulationResult run = CounterfactualStrategyKernel.Simulate(model, policy, new StrategyUncertaintyCase { Id = "baseline-coordinates" }, new StrategyKernelLimits()); Window w = W(owner, "YOMI · SIMULATION · " + policy.Name, 1160, 780); DockPanel root = Shell((run.Feasible ? "FEASIBLE" : "INFEASIBLE") + " · " + (run.Converged ? "CONVERGED" : "NONCONVERGENT"), "Policy " + policy.Name + " · " + run.Iterations + " solver iterations · model " + Short(run.ModelFingerprint, 18) + " · policy " + Short(run.PolicyFingerprint, 18)); StringBuilder text = new StringBuilder(); text.AppendLine("FINAL STRUCTURAL VALUES"); foreach (KeyValuePair<string, double> row in run.FinalValues.OrderBy(x => x.Key)) text.AppendLine("  " + row.Key.PadRight(38) + row.Value.ToString("0.########", CultureInfo.InvariantCulture).PadLeft(18)); text.AppendLine(); text.AppendLine("CONSTRAINTS"); if (run.Violations.Count == 0) text.AppendLine("  PASS · no represented constraint violations"); foreach (string violation in run.Violations) text.AppendLine("  FAIL · " + violation); text.AppendLine(); text.AppendLine("SEMANTIC BOUNDARY"); text.AppendLine("  This is a deterministic result inside the encoded structural hypothesis."); text.AppendLine("  It is not a forecast, causal identification proof or permission to execute the represented policy."); root.Children.Add(ReadOnly(text.ToString())); w.Content = root; w.Show(); AppendLedger(ctx, "POLICY_SIMULATED", policy.Id, (run.Feasible ? "FEASIBLE" : "INFEASIBLE") + " · " + (run.Converged ? "CONVERGED" : "NONCONVERGENT"), run.ModelFingerprint, run.PolicyFingerprint);
        }

        private static void OpenTwinWorld(Window owner, DeepSystemsContext ctx, WorldIndex index, StrategyModel model) { StrategyPolicy policy = ChoosePolicy(owner, model); if (policy != null) OpenTwinWorldForPolicy(owner, ctx, index, model, policy); }
        private static void OpenTwinWorldForPolicy(Window owner, DeepSystemsContext ctx, WorldIndex index, StrategyModel model, StrategyPolicy policy)
        {
            StrategyUncertaintyCase shared = new StrategyUncertaintyCase { Id = "shared-exogenous-baseline" }; StrategyPolicy baselinePolicy = new StrategyPolicy { Id = "baseline", Name = "Factual baseline" }; StrategySimulationResult factual = CounterfactualStrategyKernel.Simulate(model, baselinePolicy, shared, new StrategyKernelLimits()), counterfactual = CounterfactualStrategyKernel.Simulate(model, policy, shared, new StrategyKernelLimits()); Window w = W(owner, "YOMI · TWIN WORLD · " + policy.Name, 1200, 800); DockPanel root = Shell("SHARED-EXOGENOUS TWIN-WORLD COMPARISON", "Factual baseline and do-policy share exact exogenous coordinates. Deltas are structural-model consequences, not observed treatment effects."); List<DeltaRow> rows = model.Variables.Select(v => new DeltaRow { VariableId = v.Id, Name = v.Name, Factual = Val(factual.FinalValues, v.Id), Counterfactual = Val(counterfactual.FinalValues, v.Id) }).OrderByDescending(x => Math.Abs(x.Delta)).ToList(); ListBox list = List(); list.ItemsSource = rows; root.Children.Add(list); w.Content = root; w.Show();
        }

