=> "  ! " + x).ToArray()) + "\r\n\r\nFALSIFIERS\r\n" + String.Join("\r\n", dossier.Falsifiers.Select(x => "  × " + x).ToArray()) + "\r\n\r\nMODEL FINGERPRINT\r\n" + dossier.ModelFingerprint); Grid.SetColumn(left, 0); Grid.SetColumn(right, 1); body.Children.Add(left); body.Children.Add(right); DockPanel.SetDock(body, Dock.Top); body.Height = 470; root.Children.Add(body); root.Children.Add(EvidenceList(w, ctx, index, dossier.EvidenceNodeIds)); w.Content = root; w.Show();
