        private static void OpenAudit(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            List<StrategyAuditFinding> findings = BuildAudit(ctx, index); int failures = findings.Count(x => x.Severity == "FAIL"), warnings = findings.Count(x => x.Severity == "WARN"); Window w = W(owner, "YOMI · STRATEGY AUDIT CHAMBER", 1240, 830); DockPanel root = Shell("READ-ONLY COUNTERFACTUAL INTEGRITY AUDIT", failures + " failures · " + warnings + " warnings · " + findings.Count(x => x.Severity == "INFO") + " information findings · audit observes and never repairs"); ListBox list = List(); list.ItemsSource = findings.OrderBy(x => x.Severity == "FAIL" ? 0 : x.Severity == "WARN" ? 1 : 2).ThenBy(x => x.Code).ThenBy(x => x.SubjectId).ToList(); list.MouseDoubleClick += delegate { StrategyAuditFinding f = list.SelectedItem as StrategyAuditFinding; if (f != null && !String.IsNullOrWhiteSpace(f.NodeId) && index.Nodes.ContainsKey(f.NodeId)) WorldKernel.ExternalOpenDossier(w, ctx, index, f.NodeId); }; root.Children.Add(list); w.Content = root; w.Show(); AppendLedger(ctx, "STRATEGY_AUDIT", "store", failures + " failures · " + warnings + " warnings", HashText(String.Join("|", findings.Select(x => x.Severity + ":" + x.Code + ":" + x.SubjectId).ToArray())), "");
        }

        private static List<StrategyAuditFinding> BuildAudit(DeepSystemsContext ctx, WorldIndex index)
        {
            List<StrategyAuditFinding> rows = new List<StrategyAuditFinding>(); IEnumerable<string> ids = Store.Models.Select(x => x.Id).Concat(Store.Models.SelectMany(x => x.Variables.Select(v => v.Id))).Concat(Store.Models.SelectMany(x => x.Edges.Select(v => v.Id))).Concat(Store.Models.SelectMany(x => x.Policies.Select(v => v.Id))).Concat(Store.Models.SelectMany(x => x.Policies.SelectMany(p => p.Interventions.Select(v => v.Id)))).Concat(Store.Analyses.Select(x => x.Id)).Concat(Store.Dossiers.Select(x => x.Id)); foreach (IGrouping<string, string> duplicate in ids.Where(x => !String.IsNullOrWhiteSpace(x)).GroupBy(x => x, StringComparer.OrdinalIgnoreCase).Where(x => x.Count() > 1)) rows.Add(F("FAIL", "GLOBAL_ID_COLLISION", duplicate.Key, duplicate.Count() + " objects share identity", "")); foreach (StrategyModel model in Store.Models) { StrategyGraphDiagnostics graph = CounterfactualStrategyKernel.Diagnose(model, new StrategyKernelLimits()); foreach (string line in graph.Audit) rows.Add(F(line.StartsWith("ERROR", StringComparison.Ordinal) ? "FAIL" : line.StartsWith("WARN", StringComparison.Ordinal) ? "WARN" : "INFO", "KERNEL_GRAPH_AUDIT", model.Id, line, "")); foreach (string evidence in model.EvidenceNodeIds.Concat(model.Variables.SelectMany(x => x.EvidenceNodeIds)).Concat(model.Edges.SelectMany(x => x.EvidenceNodeIds)).Distinct(StringComparer.OrdinalIgnoreCase)) if (!index.Nodes.ContainsKey(evidence)) rows.Add(F("WARN", "WORLD_EVIDENCE_UNAVAILABLE", model.Id, evidence, evidence)); if (model.Variables.Count > MaxVariables || model.Edges.Count > MaxEdges || model.Policies.Count > MaxPolicies || model.Objectives.Count > MaxObjectives || model.Constraints.Count > MaxConstraints) rows.Add(F("FAIL", "MODEL_CAPACITY_EXCEEDED", model.Id, "Nested collection exceeds declared capacity", "")); }
            foreach (StrategyAnalysisRecord analysis in Store.Analyses) { StrategyModel model = Model(analysis.ModelId); if (model == null) rows.Add(F("FAIL", "ANALYSIS_ORPHAN_MODEL", analysis.Id, analysis.ModelId, "")); else if (!String.Equals(CounterfactualStrategyKernel.Fingerprint(model), analysis.ModelFingerprint, StringComparison.OrdinalIgnoreCase)) rows.Add(F("INFO", "HISTORICAL_MODEL_DIVERGENCE", analysis.Id, "Analysis remains bound to historical fingerprint", "")); if (String.IsNullOrWhiteSpace(analysis.CertificateHash) || analysis.CertificateHash.Length != 64) rows.Add(F("FAIL", "ANALYSIS_CERTIFICATE_MALFORMED", analysis.Id, analysis.CertificateHash, "")); }
            foreach (StrategyDecisionDossier dossier in Store.Dossiers) { if (Model(dossier.ModelId) == null) rows.Add(F("FAIL", "DOSSIER_ORPHAN_MODEL", dossier.Id, dossier.ModelId, "")); if (!Store.Analyses.Any(x => Eq(x.Id, dossier.AnalysisId))) rows.Add(F("WARN", "DOSSIER_ANALYSIS_UNAVAILABLE", dossier.Id, dossier.AnalysisId, "")); }
            string ledger = VerifyLedger(ReadLedger(ctx, 8192)); rows.Add(F(ledger.StartsWith("CHAIN VERIFIED", StringComparison.Ordinal) || ledger == "EMPTY LEDGER" ? "INFO" : "FAIL", "LEDGER_INTEGRITY", "strategy-ledger", ledger, "")); if (rows.Count == 0) rows.Add(F("INFO", "AUDIT_CLEAR", "store", "No findings", "")); return rows;
        }

        private static void OpenLedger(Window owner, DeepSystemsContext ctx)
        {
            List<StrategyLedgerRecord> rows = ReadLedger(ctx, 8192); Window w = W(owner, "YOMI · COUNTERFACTUAL LEDGER", 1240, 820); DockPanel root = Shell("SHA-256 COUNTERFACTUAL PROVENANCE CHAIN", VerifyLedger(rows) + " · append-only records bind store correlation, model fingerprints and optional analysis certificates"); ListBox list = List(); list.ItemsSource = rows.OrderByDescending(x => x.Sequence).ToList(); root.Children.Add(list); w.Content = root; w.Show();
        }

        private static StrategyModel ProjectWorldNode(DeepSystemsContext ctx, WorldNode node, string fingerprint)
        {
            StrategyModel m = NewModel("World strategy · " + (node.Label ?? node.Kind), "A bounded inspection-strategy model seeded from one exact World Passport. Graph presence supplies evidence identity, not causal identification.", "WORLD", node.Id, fingerprint); double quality = Eq(node.EvidenceClass, "OBSERVED") ? 0.8 : Eq(node.EvidenceClass, "INFERRED") ? 0.55 : 0.4; StrategyVariable signal = V("source_signal", "Source signal quality", "EXOGENOUS", quality, 0, 1, 0, true, "index"), effort = V("inspection_effort", "Inspection effort", "DECISION", 0, 0, 1, 0, false, "index"), insight = V("insight_yield", "Insight yield", "OUTCOME", 0, 0, 1, 0.05, false, "index"), error = V("misinterpretation_risk", "Misinterpretation risk", "OUTCOME", 0, 0, 1, 0.45, false, "index"); signal.EvidenceNodeIds.Add(node.Id); m.EvidenceNodeIds.Add(node.Id); m.Variables.AddRange(new[] { signal, effort, insight, error }); m.Edges.Add(E("signal_to_insight", signal, insight, 0.45)); m.Edges.Add(E("effort_to_insight", effort, insight, 0.50)); m.Edges.Add(E("signal_to_error", signal, error, -0.30)); m.Edges.Add(E("effort_to_error", effort, error, -0.20)); m.Policies.Add(P("observe", "Observe only", effort.Id, 0)); m.Policies.Add(P("inspect", "Bounded inspection", effort.Id, 0.55)); m.Policies.Add(P("descend", "Deep evidence descent", effort.Id, 0.95)); m.Objectives.Add(O(insight, "MAXIMIZE", 0.65)); m.Objectives.Add(O(error, "MINIMIZE", 0.35)); m.Constraints.Add(C(error, "<=", 0.8, "HARD")); m.Assumptions.Add("World evidence class initializes a transparent placeholder range coordinate only."); m.Assumptions.Add("No World relationship is promoted into a causal mechanism without explicit operator authoring."); PersistProjection(ctx, m, "WORLD_MODEL_PROJECTED"); return m;
        }

        private static StrategyModel ProjectResolution(DeepSystemsContext ctx, CivilResolution resolution, string fingerprint)
        {
            StrategyModel m = NewModel("Resolution strategy · " + resolution.Title, "Counterfactual organizational-strategy projection. Adoption is a policy coordinate, not evidence that the proposition is true.", "CIVILIZATION", resolution.Id, fingerprint); double evidenceBase = Math.Min(1, (resolution.EvidenceNodeIds ?? new List<string>()).Count / 10.0), deliberationBase = Math.Min(1, (resolution.Deliberation ?? new List<string>()).Count / 12.0), current = Eq(resolution.Status, "ADOPTED") ? 1 : Eq(resolution.Status, "DELIBERATING") ? 0.45 : 0; StrategyVariable evidence = V("evidence_completeness", "Evidence completeness", "EXOGENOUS", evidenceBase, 0, 1, 0, true, "index"), deliberation = V("deliberation_depth", "Deliberation depth", "EXOGENOUS", deliberationBase, 0, 1, 0, true, "index"), adoption = V("adoption_intensity", "Adoption intensity", "DECISION", current, 0, 1, 0, false, "index"), value = V("institutional_value", "Institutional value", "OUTCOME", 0, 0, 1, 0.05, false, "index"), risk = V("implementation_risk", "Implementation risk", "OUTCOME", 0, 0, 1, 0.35, false, "index"), reversibility = V("reversibility", "Reversibility", "OUTCOME", 0, 0, 1, 0.95, false, "index"); evidence.EvidenceNodeIds.AddRange(resolution.EvidenceNodeIds ?? new List<string>()); m.EvidenceNodeIds.AddRange(resolution.EvidenceNodeIds ?? new List<string>()); m.Variables.AddRange(new[] { evidence, deliberation, adoption, value, risk, reversibility }); m.Edges.Add(E("evidence_to_value", evidence, value, 0.35)); m.Edges.Add(E("deliberation_to_value", deliberation, value, 0.25)); m.Edges.Add(E("adoption_to_value", adoption, value, 0.40)); m.Edges.Add(E("evidence_to_risk", evidence, risk, -0.25)); m.Edges.Add(E("deliberation_to_risk", deliberation, risk, -0.20)); m.Edges.Add(E("adoption_to_risk", adoption, risk, 0.55)); m.Edges.Add(E("adoption_to_reversibility", adoption, reversibility, -0.65)); m.Policies.Add(P("preserve", "Preserve current posture", adoption.Id, current)); m.Policies.Add(P("deliberate", "Continue bounded deliberation", adoption.Id, 0.35)); m.Policies.Add(P("pilot", "Reversible pilot", adoption.Id, 0.60)); m.Policies.Add(P("adopt", "Full adoption abstraction", adoption.Id, 1)); m.Objectives.Add(O(value, "MAXIMIZE", 0.50)); m.Objectives.Add(O(risk, "MINIMIZE", 0.30)); m.Objectives.Add(O(reversibility, "MAXIMIZE", 0.20)); m.Constraints.Add(C(risk, "<=", 0.85, "HARD")); m.Assumptions.Add("Resolution adoption status is organizational state, not epistemic truth or causal evidence."); m.Assumptions.Add("Coefficients are explicit strategy-model hypotheses and must be revised when evidence warrants."); PersistProjection(ctx, m, "CIVIL_RESOLUTION_PROJECTED"); return m;
        }

        private static StrategyModel ProjectTheory(DeepSystemsContext ctx, LogicTheory theory, Dictionary<string, string> truth, string fingerprint)
        {
            StrategyModel m = NewModel("Theory strategy · " + theory.Name, "Counterfactual inquiry-allocation model seeded from a frozen four-valued truth spectrum. Logical support remains distinct from causal magnitude.", "LOGIC", theory.Id, fingerprint); int total = Math.Max(1, truth.Count), both = truth.Count(x => x.Value == "BOTH"), neither = truth.Count(x => x.Value == "NEITHER"), settled = truth.Count(x => x.Value == "TRUE_ONLY" || x.Value == "FALSE_ONLY"); StrategyVariable contradiction = V("contradiction_density", "Contradiction density", "EXOGENOUS", both / (double)total, 0, 1, 0, true, "index"), unknown = V("unknown_density", "Unknown density", "EXOGENOUS", neither / (double)total, 0, 1, 0, true, "index"), settledVar = V("settled_density", "One-sided support density", "EXOGENOUS", settled / (double)total, 0, 1, 0, true, "index"), inquiry = V("inquiry_intensity", "Inquiry intensity", "DECISION", 0, 0, 1, 0, false, "index"), reach = V("explanatory_reach", "Explanatory reach", "OUTCOME", 0, 0, 1, 0.1, false, "index"), error = V("epistemic_overreach", "Epistemic overreach", "OUTCOME", 0, 0, 1, 0.15, false, "index"); m.Variables.AddRange(new[] { contradiction, unknown, settledVar, inquiry, reach, error }); m.Edges.Add(E("settled_to_reach", settledVar, reach, 0.45)); m.Edges.Add(E("inquiry_to_reach", inquiry, reach, 0.45)); m.Edges.Add(E("unknown_to_reach", unknown, reach, -0.25)); m.Edges.Add(E("contradiction_to_overreach", contradiction, error, 0.45)); m.Edges.Add(E("unknown_to_overreach", unknown, error, 0.30)); m.Edges.Add(E("inquiry_to_overreach", inquiry, error, -0.25)); m.Policies.Add(P("observe", "Preserve frozen theory", inquiry.Id, 0)); m.Policies.Add(P("target", "Targeted inquiry", inquiry.Id, 0.55)); m.Policies.Add(P("adversarial", "Adversarial falsification", inquiry.Id, 0.95)); m.Objectives.Add(O(reach, "MAXIMIZE", 0.60)); m.Objectives.Add(O(error, "MINIMIZE", 0.40)); m.Constraints.Add(C(error, "<=", 0.8, "HARD")); m.Assumptions.Add("Four-valued truth counts initialize inquiry coordinates but do not identify causal coefficients."); m.Assumptions.Add("BOTH is retained as local contradiction, not collapsed into falsehood or universal failure."); PersistProjection(ctx, m, "LOGIC_THEORY_PROJECTED"); return m;
        }

        private static StrategyModel ProjectVerification(DeepSystemsContext ctx, VerificationModel source, string fingerprint)
        {
            VerificationTopology t = VerificationKernel.AnalyzeTopology(source, new VerificationKernelLimits()); double reachable = t.TotalStates == 0 ? 0 : t.ReachableStates / (double)t.TotalStates, deadlocks = t.ReachableStates == 0 ? 0 : t.Deadlocks / (double)t.ReachableStates, nondeterminism = t.ReachableStates == 0 ? 0 : t.NondeterministicStates / (double)t.ReachableStates; StrategyModel m = NewModel("Verification strategy · " + source.Name, "Strategy projection of finite-state topology. A verification PASS concerns the encoded protocol and never becomes an empirical causal claim.", "VERIFICATION", source.Id, fingerprint); StrategyVariable coverage = V("reachable_coverage", "Reachable-state coverage", "EXOGENOUS", reachable, 0, 1, 0, true, "index"), deadlock = V("deadlock_exposure", "Deadlock exposure", "EXOGENOUS", deadlocks, 0, 1, 0, true, "index"), branching = V("nondeterminism", "Nondeterminism", "EXOGENOUS", nondeterminism, 0, 1, 0, true, "index"), assurance = V("assurance_effort", "Assurance effort", "DECISION", 0, 0, 1, 0, false, "index"), confidence = V("protocol_confidence", "Protocol confidence", "OUTCOME", 0, 0, 1, 0.05, false, "index"), cost = V("assurance_cost", "Assurance cost", "OUTCOME", 0, 0, 1, 0.05, false, "index"); m.Variables.AddRange(new[] { coverage, deadlock, branching, assurance, confidence, cost }); m.Edges.Add(E("coverage_to_confidence", coverage, confidence, 0.35)); m.Edges.Add(E("deadlock_to_confidence", deadlock, confidence, -0.35)); m.Edges.Add(E("branching_to_confidence", branching, confidence, -0.15)); m.Edges.Add(E("assurance_to_confidence", assurance, confidence, 0.50)); m.Edges.Add(E("assurance_to_cost", assurance, cost, 0.75)); m.Edges.Add(E("branching_to_cost", branching, cost, 0.20)); m.Policies.Add(P("observe", "Observe current abstraction", assurance.Id, 0)); m.Policies.Add(P("inspect", "Bounded verification campaign", assurance.Id, 0.55)); m.Policies.Add(P("exhaust", "Maximum represented assurance", assurance.Id, 1)); m.Objectives.Add(O(confidence, "MAXIMIZE", 0.65)); m.Objectives.Add(O(cost, "MINIMIZE", 0.35)); m.Constraints.Add(C(cost, "<=", 0.9, "HARD")); m.Assumptions.Add("Topology statistics describe the encoded finite abstraction, not the live implementation."); m.Assumptions.Add("Assurance effort is a modeling coordinate and does not schedule or execute verification work."); PersistProjection(ctx, m, "VERIFICATION_MODEL_PROJECTED"); return m;
        }

        private static StrategyModel NewModel(string name, string charter, string sourceKind, string sourceId, string fingerprint) { return new StrategyModel { Id = Id("strategy-model"), Name = Short(name, 240), Charter = Short(charter, MaxLongText), SourceKind = sourceKind, SourceId = sourceId, SourceFingerprint = fingerprint, Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1, Horizon = 1 }; }
        private static StrategyVariable V(string token, string name, string kind, double baseline, double min, double max, double intercept, bool uncertain, string unit) { return new StrategyVariable { Id = token + "-" + Guid.NewGuid().ToString("N").Substring(0, 8), Name = name, Kind = kind, Status = "ACTIVE", Baseline = baseline, Minimum = min, Maximum = max, Intercept = intercept, Uncertain = uncertain, Unit = unit }; }
        private static StrategyEdge E(string name, StrategyVariable from, StrategyVariable to, double coefficient) { return new StrategyEdge { Id = Id("edge"), Name = name, FromVariableId = from.Id, ToVariableId = to.Id, Kind = "CAUSAL", Status = "ACTIVE", Transform = "LINEAR", Coefficient = coefficient }; }
        private static StrategyPolicy P(string token, string name, string variableId, double value) { StrategyPolicy p = new StrategyPolicy { Id = token + "-" + Guid.NewGuid().ToString("N").Substring(0, 8), Name = name, Status = "CANDIDATE", CreatedUtc = Now(), UpdatedUtc = Now() }; p.Interventions.Add(new StrategyIntervention { Id = Id("intervention"), VariableId = variableId, Name = "do(" + variableId + ")", Kind = "DO", Value = value, StartPeriod = 0, EndPeriod = Int32.MaxValue, Rationale = "Projection seed; operator-editable and modeling-only." }); return p; }
        private static StrategyObjective O(StrategyVariable variable, string direction, double weight) { return new StrategyObjective { Id = Id("objective"), VariableId = variable.Id, Name = variable.Name, Direction = direction, Weight = weight, Aspiration = direction == "MAXIMIZE" ? variable.Maximum * 0.75 : variable.Minimum + (variable.Maximum - variable.Minimum) * 0.25, Status = "ACTIVE" }; }
        private static StrategyConstraint C(StrategyVariable variable, string op, double threshold, string severity) { return new StrategyConstraint { Id = Id("constraint"), VariableId = variable.Id, Name = variable.Name + " boundary", Operator = op, Threshold = threshold, Severity = severity, Penalty = 1, Status = "ACTIVE" }; }
        private static void PersistProjection(DeepSystemsContext ctx, StrategyModel model, string evt) { Store.Models.Insert(0, model); TrimStore(); Save(ctx); AppendLedger(ctx, evt, model.Id, model.SourceKind + " · " + model.SourceId, CounterfactualStrategyKernel.Fingerprint(model), ""); }
        private static StrategyModel LatestProjection(string kind, string id) { return Store.Models.Where(x => Eq(x.SourceKind, kind) && Eq(x.SourceId, id)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).FirstOrDefault(); }

        private static void Load(DeepSystemsContext ctx)
        {
            lock (Gate) { if (Store != null && String.Equals(LoadedRoot, ctx.StateRoot, StringComparison.OrdinalIgnoreCase)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<StrategySuperstructureStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<StrategySuperstructureStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new StrategySuperstructureStore(); NormalizeStore(); }
        }
        private static void NormalizeStore()
        {
            if (Store == null) Store = new StrategySuperstructureStore(); Store.Schema = 1; Store.Models = Store.Models ?? new List<StrategyModel>(); Store.Analyses = Store.Analyses ?? new List<StrategyAnalysisRecord>(); Store.Dossiers = Store.Dossiers ?? new List<StrategyDecisionDossier>(); Store.RecentQuestions = Store.RecentQuestions ?? new List<string>(); foreach (StrategyModel m in Store.Models) { m.Variables = (m.Variables ?? new List<StrategyVariable>()).Take(MaxVariables).ToList(); m.Edges = (m.Edges ?? new List<StrategyEdge>()).Take(MaxEdges).ToList(); m.Policies = (m.Policies ?? new List<StrategyPolicy>()).Take(MaxPolicies).ToList(); m.Objectives = (m.Objectives ?? new List<StrategyObjective>()).Take(MaxObjectives).ToList(); m.Constraints = (m.Constraints ?? new List<StrategyConstraint>()).Take(MaxConstraints).ToList(); m.Assumptions = (m.Assumptions ?? new List<string>()).Take(MaxAssumptions).ToList(); m.EvidenceNodeIds = (m.EvidenceNodeIds ?? new List<string>()).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); foreach (StrategyVariable v in m.Variables) v.EvidenceNodeIds = (v.EvidenceNodeIds ?? new List<string>()).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); foreach (StrategyEdge e in m.Edges) e.EvidenceNodeIds = (e.EvidenceNodeIds ?? new List<string>()).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); foreach (StrategyPolicy p in m.Policies) { p.Interventions = (p.Interventions ?? new List<StrategyIntervention>()).Take(MaxInterventions).ToList(); p.EvidenceNodeIds = (p.EvidenceNodeIds ?? new List<string>()).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); foreach (StrategyIntervention i in p.Interventions) i.EvidenceNodeIds = (i.EvidenceNodeIds ?? new List<string>()).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); } } foreach (StrategyAnalysisRecord a in Store.Analyses) { a.Policies = a.Policies ?? new List<StrategyPolicyEvaluation>(); a.InformationValues = a.InformationValues ?? new List<StrategyInformationValue>(); } foreach (StrategyDecisionDossier d in Store.Dossiers) { d.Assumptions = d.Assumptions ?? new List<string>(); d.Objections = d.Objections ?? new List<string>(); d.Falsifiers = d.Falsifiers ?? new List<string>(); d.EvidenceNodeIds = d.EvidenceNodeIds ?? new List<string>(); }
        }
        private static void TrimStore() { NormalizeStore(); Store.Models = Store.Models.Take(MaxModels).ToList(); Store.Analyses = Store.Analyses.Take(MaxAnalyses).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxDossiers).ToList(); Store.RecentQuestions = Store.RecentQuestions.Take(MaxRecentQuestions).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("strategy-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-counterfactual-strategy.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-counterfactual-strategy-ledger.jsonl"); }

        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string modelFingerprint, string certificate)
        {
            lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<StrategyLedgerRecord> prior = ReadLedger(ctx, 8192); StrategyLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); StrategyLedgerRecord r = new StrategyLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(modelFingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { }
        }
        private static List<StrategyLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<StrategyLedgerRecord> rows = new List<StrategyLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { StrategyLedgerRecord row = Json.Deserialize<StrategyLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<StrategyLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = rows[0].PrevHash; foreach (StrategyLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(StrategyLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static StrategyModel Model(string id) { return Store.Models.FirstOrDefault(x => Eq(x.Id, id)); }
        private static StrategyModel ChooseModel(Window owner) { return ChooseObject(owner, "SELECT CAUSAL MODEL", "Choose a structural causal hypothesis", Store.Models.Where(x => Active(x.Status)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as StrategyModel; }
        private static StrategyPolicy ChoosePolicy(Window owner, StrategyModel model) { return model == null ? null : ChooseObject(owner, "SELECT POLICY", "Choose an intervention policy", model.Policies.Where(x => Active(x.Status)).Cast<object>().ToList()) as StrategyPolicy; }
        private static string PolicyName(StrategyModel model, string id) { StrategyPolicy policy = model == null ? null : model.Policies.FirstOrDefault(x => Eq(x.Id, id)); return policy == null ? id ?? "∅" : policy.Name; }
        private static void Touch(StrategyModel model) { model.Revision = Math.Max(1, model.Revision) + 1; model.UpdatedUtc = Now(); }
        private static bool Active(string status) { return !Eq(status, "ARCHIVED") && !Eq(status, "DISABLED") && !Eq(status, "RETRACTED") && !Eq(status, "REJECTED"); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static double Val(Dictionary<string, double> map, string id) { double value; return map != null && map.TryGetValue(id ?? "", out value) ? value : 0; }
        private static double Number(string raw, double fallback) { double value; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) && !Double.IsNaN(value) && !Double.IsInfinity(value) ? value : fallback; }
        private static List<string> Lines(string raw) { return (raw ?? "").Replace("\r", "").Split(new[] { '\n', ';' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).ToList(); }
        private static string DescribeNode(WorldNode n) { return "WORLD ID          " + n.Id + "\r\nKIND              " + n.Kind + "\r\nLABEL             " + n.Label + "\r\nEVIDENCE CLASS    " + n.EvidenceClass + "\r\nSOURCE            " + n.SourcePath + "\r\nJSON PATH         " + n.JsonPath + "\r\nFINGERPRINT       " + n.Fingerprint + "\r\n\r\n" + n.Summary; }
        private static ListBox EvidenceList(Window owner, DeepSystemsContext ctx, WorldIndex index, IEnumerable<string> ids) { ListBox list = List(); list.MaxHeight = 210; list.ItemsSource = (ids ?? Enumerable.Empty<string>()).Where(index.Nodes.ContainsKey).Select(x => index.Nodes[x]).ToList(); list.MouseDoubleClick += delegate { WorldNode n = list.SelectedItem as WorldNode; if (n != null) WorldKernel.ExternalOpenDossier(owner, ctx, index, n.Id); }; return list; }
        private static StrategyAuditFinding F(string severity, string code, string subject, string detail, string node) { return new StrategyAuditFinding { Severity = severity, Code = code, SubjectId = subject, Detail = detail, NodeId = node }; }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<T> TakeLast<T>(IEnumerable<T> source, int count) { Queue<T> q = new Queue<T>(); foreach (T item in source ?? Enumerable.Empty<T>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (T item in q) yield return item; }

        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 0, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static TextBox ReadOnly(string value) { return new TextBox { Text = value ?? "", IsReadOnly = true, AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Padding = new Thickness(10), Margin = new Thickness(0, 6, 6, 0), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 350, Height = 118, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }

        private static string Prompt(Window owner, string title, string label, string initial)
        {
            Window w = W(owner, "YOMI · " + title, 660, 280); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null;
        }
        private static string PromptLarge(Window owner, string title, string label, string initial)
        {
            Window w = W(owner, "YOMI · " + title, 780, 540); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.NoWrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null;
        }
        private static string Choose(Window owner, string title, string label, IEnumerable<string> choices, string preferred) { object selected = ChooseObject(owner, title, label, (choices ?? Enumerable.Empty<string>()).Cast<object>().ToList(), preferred); return selected == null ? null : Convert.ToString(selected, CultureInfo.InvariantCulture); }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { return ChooseObject(owner, title, label, choices, null); }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices, string preferred)
        {
            Window w = W(owner, "YOMI · " + title, 700, 470); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (!String.IsNullOrWhiteSpace(preferred)) list.SelectedItem = list.Items.Cast<object>().FirstOrDefault(x => Eq(Convert.ToString(x, CultureInfo.InvariantCulture), preferred)); if (list.SelectedIndex < 0 && list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null;
        }

        private sealed class DeltaRow { public string VariableId; public string Name; public double Factual; public double Counterfactual; public double Delta { get { return Counterfactual - Factual; } } public override string ToString() { return (Name ?? VariableId ?? "VARIABLE").PadRight(36) + "   factual " + Factual.ToString("0.######", CultureInfo.InvariantCulture).PadLeft(12) + "   counterfactual " + Counterfactual.ToString("0.######", CultureInfo.InvariantCulture).PadLeft(12) + "   Δ " + Delta.ToString("+0.######;-0.######;0", CultureInfo.InvariantCulture).PadLeft(13); } }
        private sealed class StrategyAuditFinding { public string Severity; public string Code; public string SubjectId; public string Detail; public string NodeId; public override string ToString() { return (Severity ?? "INFO").PadRight(5) + "   ·   " + (Code ?? "AUDIT").PadRight(34) + "   ·   " + (SubjectId ?? "∅") + "   ·   " + (Detail ?? ""); } }
    }
